class UserApiTest {
  private val server = MockWebServer()
  private lateinit var api: UserApi

  @BeforeTest fun setUp() {
    server.start()
    api = Retrofit.Builder()
      .baseUrl(server.url("/"))
      .client(OkHttpClient.Builder().addInterceptor(AuthInterceptor { "token" }).build())
      .addConverterFactory(json.asConverterFactory("application/json".toMediaType()))
      .build()
      .create()
  }

  @AfterTest fun tearDown() { server.shutdown() }

  @Test fun `sends the auth header and decodes the body`() = runTest {
    server.enqueue(MockResponse().setBody(fixture("user_200.json")))

    val user = api.getUser(42)

    val sent = server.takeRequest()                   // assert the REQUEST too
    assertEquals("/users/42", sent.path)
    assertEquals("Bearer token", sent.getHeader("Authorization"))
    assertEquals("Ada", user.fullName)
  }

  @Test fun `an unknown field does not break decoding`() = runTest {
    // the fixture carries a field the DTO does not model
    server.enqueue(MockResponse().setBody(fixture("user_200_extra_field.json")))
    assertEquals(1L, api.getUser(1).id)
  }

  @Test fun `a dropped connection surfaces as IOException`() = runTest {
    server.enqueue(MockResponse().setSocketPolicy(SocketPolicy.DISCONNECT_AT_START))
    assertFailsWith<IOException> { api.getUser(1) }
  }

  @Test fun `parallel 401s trigger exactly one refresh`() = runTest {
    repeat(3) { server.enqueue(MockResponse().setResponseCode(401)) }
    server.enqueue(MockResponse().setBody(fixture("refresh_200.json")))
    repeat(3) { server.enqueue(MockResponse().setBody(fixture("user_200.json"))) }

    coroutineScope { List(3) { async { api.getUser(1) } }.awaitAll() }

    assertEquals(1, server.requestCount { it.path == "/auth/refresh" })
  }
}

