class UserRepository(private val api: UserApi) {

  // ❌ an extra thread hop that protects nothing — the call already suspends
  suspend fun wrong(id: Long): UserDto = withContext(Dispatchers.IO) { api.getUser(id) }

  // ✅ main-safe by contract: enqueued on OkHttp's pool, parsed there, resumed here
  suspend fun user(id: Long): UserDto = api.getUser(id)

  // ✅ execute() blocks the caller, so this one genuinely needs a dispatcher
  suspend fun legacy(id: Long): UserDto = withContext(Dispatchers.IO) {
    api.getUserCall(id).execute().body() ?: error("empty body")
  }

  // ✅ the network part needs nothing; the CPU-bound part goes to Default
  suspend fun report(id: Long): Report {
    val dto = api.getUser(id)
    return withContext(Dispatchers.Default) { buildReport(dto) }
  }
}

