  .baseUrl("https://api.example.com/")
  .client(client)
  // factories are asked in order, first answer wins: Scalars before Json, or a
  // String return type gets handed to the JSON parser
  .addConverterFactory(ScalarsConverterFactory.create())
  .addConverterFactory(json.asConverterFactory("application/json".toMediaType()))
  .validateEagerly(BuildConfig.DEBUG)   // parse every method now: crash in debug, not in prod
  .build()

// No class was generated at build time — this is a Proxy
val api: UserApi = retrofit.create(UserApi::class.java)

// Roughly what create() does
val proxy = Proxy.newProxyInstance(
  UserApi::class.java.classLoader,
  arrayOf(UserApi::class.java)
) { _, method, args ->
  val serviceMethod = cache.getOrPut(method) { ServiceMethod.parseAnnotations(method) }
  serviceMethod.invoke(args)            // build request -> OkHttp Call -> convert body
}

interface UserApi {
  // The typo is found on the first call to this method — or at create() with
  // validateEagerly: "URL "users/{id}" does not contain {userId}"
  @GET("users/{id}")
  suspend fun user(@Path("userId") id: Long): UserDto
}

// Defaults: 64 in flight, 5 per host, applied to enqueue() — which is what every
// Retrofit suspend function uses. Blocking execute() calls are counted, not throttled.
val dispatcher = Dispatcher().apply {
  maxRequests = 64
  maxRequestsPerHost = 15        // HTTP/2 multiplexes them onto one connection
}

val client = OkHttpClient.Builder()
  .dispatcher(dispatcher)
  .connectionPool(ConnectionPool(5, 5, TimeUnit.MINUTES))   // idle conns, keep-alive
  .callTimeout(30, TimeUnit.SECONDS)
  .build()

// A stream never finishes: five of them and every other call to that host queues.
// Own dispatcher, shared pool and interceptors.
val streamingClient = client.newBuilder()
  .dispatcher(Dispatcher())
  .callTimeout(0, TimeUnit.MILLISECONDS)      // no budget for a long-lived call
  .readTimeout(0, TimeUnit.MILLISECONDS)
  .build()

// Share the client, never rebuild it: a fresh Builder is a fresh pool and a
// fresh TLS handshake on every call
val imageLoader = ImageLoader.Builder(context)
  .components { add(OkHttpNetworkFetcherFactory(callFactory = { client })) }
  .build()

// What to print when latency looks unexplainable
Log.d(
  "net",
  "running=${client.dispatcher.runningCallsCount()} queued=${client.dispatcher.queuedCallsCount()}"
)

interface FilesApi {
  @Streaming                                  // no buffering: you get the live stream
  @GET("files/{name}")
  suspend fun download(
    @Path("name") name: String,
    @Header("Range") range: String?,
    @Header("If-Range") etag: String?
  ): Response<ResponseBody>
}

// callTimeout bounds the whole call including the body — off for downloads
val downloadClient = client.newBuilder()
  .callTimeout(0, TimeUnit.MILLISECONDS)
  .readTimeout(30, TimeUnit.SECONDS)          // inactivity is the right guard
  .build()

suspend fun download(api: FilesApi, name: String, part: File, etag: String?): Long {
  val done = if (part.exists()) part.length() else 0L
  val response = api.download(name, if (done > 0) "bytes=$done-" else null, etag)
  val body = response.body() ?: error("no body")

  // 206: the range was honoured. 200: it was ignored, so start over.
  val resumed = response.code() == 206
  val total = response.headers()["Content-Range"]?.substringAfter('/')?.toLongOrNull()

  body.use { source ->
    val sink = if (resumed) part.appendingSink() else part.sink()
    sink.buffer().use { it.writeAll(source.source()) }
  }
  return total ?: part.length()
}

class DownloadWorker(ctx: Context, p: WorkerParameters) : CoroutineWorker(ctx, p) {
  override suspend fun doWork(): Result = try {
    setForeground(progressNotification())     // long-running work must be foreground
    download(api, name, partFile, storedEtag)
    partFile.renameTo(target)                 // publish only when complete
    Result.success()
  } catch (e: IOException) {
    Result.retry()                            // the .part file is the resume point
  }
}
